function validateMacAddress(macAddress) {
    const macRegex = /^([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}$/;
    if (!macRegex.test(macAddress)) {
        return {
            valid: false,
            error: "Invalid MAC address format"
        };
    }

    const octets = macAddress.split(":");
    const firstOctet = parseInt(octets[0], 16);
    const secondOctet = parseInt(octets[1], 16);

    const isUnicast = (firstOctet & 1) === 0;
    const isMulticast = !isUnicast;
    const isUniversallyAdministered = (secondOctet & 2) === 0;
    const isLocallyAdministered = !isUniversallyAdministered;

    return {
        valid: true,
        macAddress,
        isUnicast,
        isMulticast,
        isUniversallyAdministered,
        isLocallyAdministered
    };
}
