class FileSystem:
    def __init__(self, params: Dict[str, str]):
        self.taskDir = params['taskDir']

    def _get_filepath(self, task_id: str) -> str:
        return os.path.join(self.taskDir, task_id)

    def save_task(self, task_data: Dict[str, Union[str, int]]) -> Dict[str, Union[str, int]]:
        if 'id' not in task_data:
            task_data['id'] = str(uuid.uuid4())
        task_id = task_data['id']
        filepath = self._get_filepath(task_id)
        with open(filepath, 'w') as f:
            json.dump(task_data, f)
        return task_data

    def delete_task(self, task_id: str) -> None:
        filepath = self._get_filepath(task_id)
        if os.path.exists(filepath):
            os.remove(filepath)

    def find_by_id(self, task_id: str) -> Dict[str, Union[str, int]]:
        filepath = self._get_filepath(task_id)
        with open(filepath, 'r') as f:
            return json.load(f)

    def find_by_ids(self, task_ids: List[str]) -> List[Dict[str, Union[str, int]]]:
        return [self.find_by_id(task_id) for task_id in task_ids]

    def all_task_data(self, order: str = 'asc') -> List[Dict[str, Union[str, int]]]:
        tasks = []
        for filename in os.listdir(self.taskDir):
            filepath = os.path.join(self.taskDir, filename)
            with open(filepath, 'r') as f:
                tasks.append(json.load(f))
        if order == 'desc':
            tasks.sort(key=lambda x: x['id'], reverse=True)
        else:
            tasks.sort(key=lambda x: x['id'])
        return tasks

    def task_data(self, task_id: str) -> Union[Dict[str, Union[str, int]], None]:
        try:
            return self.find_by_id(task_id)
        except FileNotFoundError:
            return None
